from author import page, section as s
import sys

def write(id, locale, title, description, lead, sections, related):
    page(id, locale, 'overview' if id == 'aifield' else 'detail', title, description,
         'AIFIELD / ' + ('PHOTONIC ENGINEERING' if locale == 'en' else 'INŻYNIERIA FOTONICZNA'),
         lead, sections, related, project='aifield',
         maturity='September 2026 source snapshot · current access by discussion' if locale == 'en' else 'Stan opisany we wrześniu 2026 · aktualny dostęp do uzgodnienia')

def overview():
    write('aifield','en','From photonic idea to an inspectable design.','AIFIELD connects photonic design and classical simulation, with partial AI assistance and a separate neural field research direction.','Tools for engineers who need to move between a photonic structure, its assumptions and the behavior predicted by a model.',[
        s('users','A working context for photonic engineering.','Designing an optical component involves more than drawing its outline. Geometry, materials, layers and the intended process all shape the question a simulation can answer. AIFIELD is presented as a place to connect that design work with model-based investigation.','Its intended users include photonic designers and researchers assessing candidate structures. The useful output is an inspectable engineering design and simulation result, with enough context to understand what was modeled.',links=['aifield-design']),
        s('classical','The classical toolchain, as described in September 2026.','The supplied demonstration summary describes geometry, layer and process handling alongside mode, circuit, field and thermal simulation work. These are dated capability descriptions; they do not establish the availability or support status of every function today.','The workflow moves from a design question through setup and execution to result inspection. Agent assistance can help with parts of that process, while a person remains responsible for applying and reviewing proposed changes.',links=['aifield-design','aifield-ai']),
        s('research','A separate question: can a network predict the field?','Neural optical-field prediction explores whether a learned model can provide useful field estimates. The supplied research depends on conditions including boundary information. Generalization, larger stitched domains and practical speed advantage remain open questions.','This research is distinct from the classical design tools and from ArtiSense’s proposed analog signal-interpretation processor.',links=['aifield-neural']),
        s('example','One internal design example. Two different questions.','The photonic glucose chip-design example connects the projects. AIFIELD concerns the geometry, design workflow and simulated behavior. ArtiSense concerns the intended sensing outcome and what would be needed to validate it.','Internal design work is useful evidence of an engineering activity. It is not a customer deployment, fabricated-chip measurement or validation of glucose accuracy.',links=['aifield-validation','artisense']),
        s('access','Start with the engineering question.','A demo request starts a conversation about the design task, available workflow and limitations. It does not create an account or grant immediate software access. Describe the structure you want to investigate and the result you need to inspect; avoid sending confidential design files in the initial enquiry.',links=['investors','partnerships'])],['aifield-design','aifield-ai','aifield-neural','aifield-validation','artisense','investors'])
    write('aifield','pl','Od pomysłu fotonicznego do projektu, który można ocenić.','AIFIELD łączy projektowanie fotoniki i klasyczne symulacje z częściowym wsparciem AI oraz odrębnymi badaniami neuronowych modeli pola.','Narzędzia dla inżynierów, którzy potrzebują powiązać strukturę fotoniczną, jej założenia i zachowanie przewidywane przez model.',[
        s('users','Kontekst pracy nad fotoniką.','Projektowanie elementu optycznego wymaga więcej niż narysowania jego obrysu. Geometria, materiały, warstwy i planowany proces określają pytanie, na które może odpowiedzieć symulacja. AIFIELD jest przedstawiany jako środowisko łączące projekt z badaniem modelowym.','Docelowi użytkownicy to projektanci fotoniki i badacze oceniający proponowane struktury. Użytecznym wynikiem jest projekt inżynierski oraz rezultat symulacji, którego kontekst pozwala zrozumieć, co zamodelowano.',links=['aifield-design']),
        s('classical','Klasyczne narzędzia według opisu z września 2026.','Dostarczone podsumowanie demonstracji opisuje obsługę geometrii, warstw i procesów oraz prace nad symulacją modów, obwodów, pola i zjawisk cieplnych. Są to opisy możliwości z określonego momentu, które nie potwierdzają dzisiejszej dostępności ani wsparcia każdej funkcji.','Proces prowadzi od pytania projektowego przez przygotowanie i wykonanie obliczeń do oceny wyniku. Agent może pomagać w wybranych działaniach, a człowiek odpowiada za zastosowanie i sprawdzenie proponowanych zmian.',links=['aifield-design','aifield-ai']),
        s('research','Odrębne pytanie: czy sieć może przewidzieć pole?','Neuronowe przewidywanie pola optycznego bada możliwość uzyskiwania użytecznych oszacowań przez wyuczony model. Opisane badania zależą od warunków, w tym dostarczonej informacji brzegowej. Generalizacja, większe łączone obszary i praktyczna przewaga czasowa pozostają otwarte.','To kierunek odrębny od klasycznych narzędzi projektowych i proponowanego analogowego procesora interpretacji sygnałów ArtiSense.',links=['aifield-neural']),
        s('example','Jeden wewnętrzny przykład. Dwa różne pytania.','Przykład projektu fotonicznego chipu do badań nad pomiarem glukozy łączy oba projekty. AIFIELD dotyczy geometrii, procesu projektowania i symulowanego zachowania. ArtiSense dotyczy zamierzonego pomiaru i wymagań jego walidacji.','Wewnętrzna praca projektowa jest użytecznym dowodem działania inżynierskiego. Nie stanowi wdrożenia u klienta, pomiaru wykonanego chipu ani walidacji dokładności pomiaru glukozy.',links=['aifield-validation','artisense']),
        s('access','Zacznij od pytania inżynierskiego.','Prośba o demo rozpoczyna rozmowę o zadaniu, dostępnych narzędziach i ograniczeniach. Nie tworzy konta ani nie daje natychmiastowego dostępu do programu. Opisz badaną strukturę i potrzebny wynik; w pierwszym zapytaniu nie przesyłaj poufnych plików projektowych.',links=['investors','partnerships'])],['aifield-design','aifield-ai','aifield-neural','aifield-validation','artisense','investors'])

def design():
    write('aifield-design','en','Connect the structure to the simulation.','Geometry, layers, process assumptions and classical simulation tasks in the September 2026 AIFIELD design workflow.','An engineering result is useful when you can trace it back to the design choices and conditions that produced it.',[
        s('setup','Define the object before asking the solver.','The September 2026 summary describes geometry and layer/process handling. These provide the context for a photonic structure: what is drawn, which materials and layers it represents, and which process assumptions are being used.','A useful setup also identifies the question: a mode property, circuit response, spatial field or thermal effect. The supplied material does not establish a complete supported-format list, process library or fabrication-ready export guarantee.'),
        s('tasks','Choose a model for the question.','The source describes work in four classical simulation areas. Their outputs answer different engineering questions and should be interpreted within the corresponding inputs and assumptions.',rows=[['Modes','Study supported optical behavior in a specified structure. Geometry, material and boundary assumptions remain part of the result.'],['Circuits','Investigate response at the connected-component level. Component models and their valid range matter.'],['Fields','Inspect spatial optical behavior in a modeled domain. Sources, boundaries and discretization affect interpretation.'],['Thermal work','Investigate modeled temperature behavior and its engineering context. Thermal inputs and coupling assumptions require review.']]),
        s('sequence','Carry the inputs through to the result.','Begin with the geometry and model definition. Review the setup before executing the selected tool. Inspect the resulting output alongside its parameters, then change one justified aspect of the design and compare again.','This explanatory sequence makes the responsibilities visible; it is not a claim that every step is automated or every solver has been independently validated. The engineer must assess whether the chosen model represents the intended physical question.',links=['aifield-ai']),
        s('limits','A model is a conditional answer.','The supplied summary does not include solver settings, convergence records or numerical benchmark tables sufficient for reproduction here. No universal accuracy, runtime or manufacturing compatibility is asserted.','For a technical discussion, identify the required inputs, expected output and reference comparison. Current format support, access and practical limits must be confirmed for that task.',links=['aifield-validation','contact'])],['aifield-validation','aifield-ai','contact'])
    write('aifield-design','pl','Połącz strukturę z symulacją.','Geometria, warstwy, założenia procesu i klasyczne zadania symulacyjne w procesie projektowym AIFIELD opisanym we wrześniu 2026.','Wynik inżynierski jest użyteczny, gdy można powiązać go z decyzjami projektowymi i warunkami, w których powstał.',[
        s('setup','Określ obiekt przed uruchomieniem obliczeń.','Podsumowanie z września 2026 opisuje obsługę geometrii oraz warstw i procesów. Określają one kontekst struktury fotonicznej: narysowany kształt, reprezentowane materiały i warstwy oraz przyjęte założenia technologiczne.','Przygotowanie obejmuje także pytanie: własność modu, odpowiedź obwodu, rozkład pola czy efekt cieplny. Dostarczony materiał nie ustala pełnej listy formatów, biblioteki procesów ani gwarancji eksportu gotowego do wytworzenia.'),
        s('tasks','Dobierz model do pytania.','Źródło opisuje prace w czterech obszarach klasycznej symulacji. Ich wyniki odpowiadają na różne pytania inżynierskie i należy je interpretować w granicach odpowiednich danych wejściowych i założeń.',rows=[['Mody','Badanie zachowania optycznego w określonej strukturze. Geometria, materiały i warunki brzegowe pozostają częścią wyniku.'],['Obwody','Badanie odpowiedzi na poziomie połączonych elementów. Ważne są modele elementów i zakres ich stosowalności.'],['Pole','Analiza przestrzennego zachowania optycznego w modelowanym obszarze. Źródła, brzegi i dyskretyzacja wpływają na interpretację.'],['Zjawiska cieplne','Badanie modelowanego rozkładu temperatury i jego znaczenia inżynierskiego. Dane cieplne i założenia sprzężeń wymagają oceny.']]),
        s('sequence','Zachowaj związek danych z wynikiem.','Zacznij od geometrii i definicji modelu. Oceń ustawienia przed wykonaniem wybranego obliczenia. Sprawdź wynik wraz z parametrami, następnie zmień uzasadniony element projektu i ponownie porównaj.','Ta objaśniająca sekwencja pokazuje odpowiedzialności; nie oznacza automatyzacji każdego kroku ani niezależnej walidacji wszystkich narzędzi. Inżynier ocenia, czy model odpowiada zamierzonemu pytaniu fizycznemu.',links=['aifield-ai']),
        s('limits','Model daje odpowiedź warunkową.','Dostarczone podsumowanie nie zawiera ustawień solverów, zapisów zbieżności ani tabel wyników wystarczających do odtworzenia obliczeń na tej stronie. Nie deklarujemy uniwersalnej dokładności, czasu działania ani zgodności produkcyjnej.','W rozmowie technicznej określ potrzebne dane, oczekiwany wynik i porównanie odniesienia. Bieżąca obsługa formatów, dostęp i praktyczne ograniczenia wymagają potwierdzenia dla danego zadania.',links=['aifield-validation','contact'])],['aifield-validation','aifield-ai','contact'])

def ai():
    write('aifield-ai','en','Assistance with a human review point.','How AIFIELD explores command-line and MCP agent assistance: proposed actions, human application, tool execution and result review.','An instruction can start a useful engineering action. It does not remove the need to check what the tool changed or what the result means.',[
        s('instruction','Turn an intention into a proposed action.','A person defines the task and relevant design context. An assistant may propose a sequence of changes or tool calls. The September 2026 material describes partial assistance through command-line and Model Context Protocol (MCP) workflows.','A command-line interface exposes an explicit operation. MCP provides a way for an assistant to call exposed tools. Neither interface establishes that a proposed operation is physically appropriate or safe to accept without review.'),
        s('review','Application and review remain human responsibilities.','The described workflow includes human application and review of proposals. Before accepting a change, inspect its target, parameters and effect on the design. After tool execution, compare the output with the intended engineering question.','An apparently successful tool call can still use the wrong geometry, boundary condition or interpretation. A failed or incomplete call needs an explicit outcome before further actions build on it. This is not evidence of autonomous end-to-end chip design.',links=['aifield-design']),
        s('data','Know where the information goes.','The local solver and the assistant are separate processing boundaries. Running a solver locally does not establish that every prompt, design excerpt or returned result remains local. The supplied summary does not settle which assistant providers or external processing settings apply to a particular deployment.','Before sharing sensitive work, confirm which data leaves the machine, which service receives it, retention settings and access permissions. No blanket confidentiality guarantee is made here; the initial enquiry should describe a non-confidential task.'),
        s('limits','Inspect the whole sequence, including failures.','A useful demonstration should show the user instruction, proposed action, accepted changes, executed command and inspected result. It should also show what happens when a tool is unavailable or the output is ambiguous.','The current source supports partial workflow assistance. Broader automation, unattended reliability and current access remain questions for a scoped demonstration.',links=['aifield-validation','contact'])],['aifield-design','aifield-validation','contact'])
    write('aifield-ai','pl','Wsparcie z miejscem na ocenę człowieka.','Jak AIFIELD bada wsparcie agentowe przez CLI i MCP: propozycje działań, zastosowanie przez człowieka, wykonanie narzędzi i ocena wyników.','Polecenie może rozpocząć użyteczne działanie inżynierskie. Nadal trzeba sprawdzić, co narzędzie zmieniło i co oznacza wynik.',[
        s('instruction','Od zamiaru do propozycji działania.','Człowiek określa zadanie i potrzebny kontekst projektu. Asystent może zaproponować zmiany lub wywołania narzędzi. Materiał z września 2026 opisuje częściowe wsparcie przez interfejs wiersza poleceń oraz Model Context Protocol (MCP).','Interfejs wiersza poleceń udostępnia określoną operację. MCP umożliwia asystentowi wywoływanie udostępnionych narzędzi. Żaden z tych interfejsów nie potwierdza fizycznej zasadności operacji ani nie zastępuje jej oceny.'),
        s('review','Zastosowanie i ocena pozostają po stronie człowieka.','Opisany proces obejmuje zastosowanie i sprawdzenie propozycji przez człowieka. Przed przyjęciem zmiany należy ocenić jej cel, parametry i wpływ na projekt. Po wykonaniu narzędzia trzeba porównać wynik z pytaniem inżynierskim.','Wywołanie zakończone bez błędu może nadal dotyczyć niewłaściwej geometrii, warunków brzegowych lub interpretacji. Nieudane bądź niepełne działanie wymaga rozstrzygnięcia przed kolejnymi krokami. Nie jest to dowód autonomicznego projektowania chipów od początku do końca.',links=['aifield-design']),
        s('data','Ustal, gdzie trafiają informacje.','Lokalny solver i asystent stanowią odrębne granice przetwarzania. Lokalne obliczenia nie oznaczają, że każde polecenie, fragment projektu lub wynik pozostaje na komputerze. Podsumowanie nie rozstrzyga, jaki dostawca asystenta ani ustawienia przetwarzania zewnętrznego dotyczą konkretnego wdrożenia.','Przed udostępnieniem wrażliwych danych ustal, co opuszcza komputer, do jakiej usługi trafia oraz jakie są zasady retencji i dostępu. Nie deklarujemy ogólnej gwarancji poufności; pierwsze zapytanie powinno opisywać niepoufne zadanie.'),
        s('limits','Oceń całą sekwencję, także niepowodzenia.','Użyteczna demonstracja powinna pokazać polecenie użytkownika, propozycję, przyjęte zmiany, wykonane polecenie i oceniony wynik. Powinna również wyjaśniać zachowanie przy niedostępnym narzędziu lub niejednoznacznym rezultacie.','Obecne źródło uzasadnia częściowe wsparcie procesu. Szersza automatyzacja, niezawodność bez nadzoru i bieżący dostęp pozostają tematami demonstracji o uzgodnionym zakresie.',links=['aifield-validation','contact'])],['aifield-design','aifield-validation','contact'])

def neural():
    write('aifield-neural','en','What could a learned field model predict?','AIFIELD neural optical-field research: supplied boundary information, experimental context, generalization, domain stitching and unresolved speed advantage.','A research question about optical fields, with conditions that matter as much as the prediction itself.',[
        s('question','Explore a learned approximation of optical behavior.','The neural research direction asks whether a learned model can estimate an optical field for a defined problem. It is a separate investigation from the classical design and simulation workflow described elsewhere.','A promising prediction in a selected setting does not establish a general solver. The input information, training context, evaluated structures and reference all determine what the result can support.',links=['aifield-design']),
        s('boundaries','Boundary information is part of the experiment.','The supplied September 2026 research summary describes results under conditions that include supplied boundary information. That information constrains the problem. It must remain visible when interpreting a result or comparing the method with another approach.','A prediction using such information cannot be presented as an equivalent demonstration of prediction from scratch. The original plots, complete settings and numerical comparisons are not provided in this package, so no reconstructed accuracy chart is shown.'),
        s('limits','Four questions before broader use.','The research needs to be assessed beyond a favorable individual example. The summary identifies limits that affect practical interpretation.',rows=[['From-scratch prediction','What information must already be known, and how much of the physical problem is solved by supplying it?'],['Generalization','Does the method remain useful for structures and conditions outside the evaluated context?'],['Stitched domains','Can local predictions form a consistent larger field without unacceptable boundary mismatch?'],['Practical speed','Does an advantage remain after preparation, boundary information, prediction and checking are included?']]),
        s('next','Make the next comparison answer a narrower question.','A useful next study would state its reference, input information, domain and acceptance criteria before comparing predictions. It should retain successful and unsuccessful cases, and report the work needed to obtain an end-to-end result.','These are proposed research questions, not a confirmed experiment schedule. The supplied summary does not establish universal accuracy or a practical speed advantage. An investment or collaboration discussion should keep that uncertainty explicit.',links=['aifield-validation','investors','partnerships'])],['aifield-design','aifield-validation','investors','partnerships'])
    write('aifield-neural','pl','Co może przewidzieć wyuczony model pola?','Badania neuronowych modeli pola optycznego w AIFIELD: informacja brzegowa, kontekst eksperymentów, generalizacja, łączenie obszarów i czas obliczeń.','Pytanie badawcze dotyczące pola optycznego, w którym warunki są równie ważne jak samo przewidywanie.',[
        s('question','Badanie wyuczonego przybliżenia zachowania optycznego.','Kierunek neuronowy bada, czy wyuczony model może oszacować pole optyczne dla określonego problemu. Jest to odrębne badanie względem klasycznego procesu projektowania i symulacji opisanego na innych stronach.','Obiecujący wynik w wybranych warunkach nie dowodzi istnienia uniwersalnego solvera. Dane wejściowe, kontekst uczenia, oceniane struktury i odniesienie określają, co można wywnioskować z wyniku.',links=['aifield-design']),
        s('boundaries','Informacja brzegowa jest częścią eksperymentu.','Dostarczone podsumowanie badań z września 2026 opisuje wyniki przy warunkach obejmujących dostarczoną informację brzegową. Ogranicza ona problem i musi pozostać widoczna przy interpretacji wyniku oraz porównaniu metod.','Przewidywania wykorzystującego taką informację nie można przedstawiać jako równoważnego dowodu przewidywania od zera. Pakiet nie zawiera oryginalnych wykresów, pełnych ustawień ani porównań liczbowych, dlatego nie pokazujemy odtworzonego wykresu dokładności.'),
        s('limits','Cztery pytania przed szerszym użyciem.','Badania wymagają oceny wykraczającej poza pojedynczy korzystny przykład. Podsumowanie wskazuje ograniczenia wpływające na praktyczną interpretację.',rows=[['Przewidywanie od zera','Jakie informacje muszą być wcześniej znane i jaka część problemu fizycznego zostaje rozwiązana przez ich dostarczenie?'],['Generalizacja','Czy metoda pozostaje użyteczna dla struktur i warunków spoza ocenionego kontekstu?'],['Łączenie obszarów','Czy lokalne przewidywania tworzą spójne większe pole bez niedopuszczalnych niezgodności na granicach?'],['Praktyczna szybkość','Czy przewaga utrzymuje się po uwzględnieniu przygotowania, informacji brzegowej, przewidywania i kontroli?']]),
        s('next','Kolejne porównanie powinno rozstrzygać węższe pytanie.','Użyteczne badanie określiłoby odniesienie, dane wejściowe, obszar i kryteria oceny przed porównaniem przewidywań. Powinno zachować zarówno udane, jak i nieudane przypadki oraz opisać pracę potrzebną do uzyskania całego wyniku.','To proponowane pytania badawcze, a nie potwierdzony harmonogram eksperymentów. Podsumowanie nie wykazuje uniwersalnej dokładności ani praktycznej przewagi czasowej. Rozmowa inwestycyjna lub o współpracy powinna uwzględniać tę niepewność.',links=['aifield-validation','investors','partnerships'])],['aifield-design','aifield-validation','investors','partnerships'])

def validation():
    write('aifield-validation','en','A design example. An evidence boundary.','The internal photonic glucose chip-design example, classical simulation comparisons and the limits of the available AIFIELD evidence.','Follow the engineering activity without confusing a design output with a measured sensing result.',[
        s('example','The internal photonic glucose design.','The September 2026 demonstration material includes an internal photonic glucose chip-design example. It connects an intended sensing question with the work of defining a photonic structure and investigating its modeled behavior.','This is internal design activity. No external customer, production deployment or fabricated-chip measurement is established by the supplied account. The ArtiSense evidence page owns the separate question of sensing validation.',links=['artisense-validation']),
        s('workflow','Read the example as a sequence of engineering decisions.','The explanatory sequence begins with a sensing objective and candidate optical structure. Geometry and model assumptions define what can be simulated. The resulting design and modeled response can then be inspected to identify what is worth changing or investigating physically.','The available summary supports describing this activity qualitatively. It does not provide an original layout file or numerical output that can be reproduced here. The diagram on this page explains the sequence; it is not a screenshot or plot from the experiment.',links=['aifield-design']),
        s('comparison','What a simulation comparison needs.','The source refers to internal comparisons. To interpret a comparison, the reader needs the reference method, matching geometry and materials, source and boundary conditions, numerical settings and the quantity being compared.','The supplied summary does not contain those details at reproduction depth. It also does not quantify successful and unsuccessful cases. Missing numbers are left missing; no benchmark score or blanket agreement claim is inferred.',rows=[['Design workflow','An internal example is described. This supports discussion of engineering work, not a claim of customer adoption.'],['Classical comparison','Internal comparisons are mentioned; reference settings and numerical successes or misses are unavailable here.'],['Neural prediction','A separate research line with boundary, generalization and stitching limitations.'],['Physical measurement','Fabrication and measured sensing performance are not established by this design example.']]),
        s('next','Make the next evidence package reproducible.','A proposed next milestone is an inspectable design-and-simulation record: versioned inputs, tool settings, reference conditions, results and known discrepancies. A subsequent physical comparison would need its own fabrication and measurement evidence.','These are evidence needs, not completed milestones or promised dates. A scoped demo can clarify which parts of the workflow are currently available and what would be needed to evaluate a specific engineering task.',links=['aifield-neural','investors','contact'])],['aifield-design','aifield-neural','artisense-validation','investors','contact'])
    write('aifield-validation','pl','Przykład projektu. Granica dowodów.','Wewnętrzny przykład projektu fotonicznego chipu glukozowego, porównania klasycznych symulacji i ograniczenia dostępnych dowodów AIFIELD.','Prześledź działania inżynierskie, zachowując różnicę między wynikiem projektowania a zmierzonym rezultatem pomiarowym.',[
        s('example','Wewnętrzny projekt fotoniczny związany z glukozą.','Materiał demonstracyjny z września 2026 obejmuje wewnętrzny przykład projektu fotonicznego chipu do badań nad pomiarem glukozy. Łączy zamierzone pytanie pomiarowe z definiowaniem struktury fotonicznej i badaniem jej zachowania w modelu.','To wewnętrzna praca projektowa. Dostarczony opis nie potwierdza zewnętrznego klienta, wdrożenia produkcyjnego ani pomiaru wykonanego chipu. Odrębne pytanie o walidację pomiaru omawia strona dowodów ArtiSense.',links=['artisense-validation']),
        s('workflow','Odczytaj przykład jako ciąg decyzji inżynierskich.','Objaśniająca sekwencja zaczyna się od celu pomiarowego i proponowanej struktury optycznej. Geometria i założenia modelu określają możliwą symulację. Projekt i modelowaną odpowiedź można następnie ocenić, aby wskazać potrzebne zmiany lub badania fizyczne.','Podsumowanie uzasadnia jakościowy opis tej pracy. Nie zawiera oryginalnego pliku projektu ani wyniku liczbowego możliwego do odtworzenia na stronie. Diagram objaśnia kolejność; nie jest zrzutem interfejsu ani wykresem eksperymentu.',links=['aifield-design']),
        s('comparison','Czego wymaga porównanie symulacji.','Źródło wspomina o porównaniach wewnętrznych. Ich interpretacja wymaga metody odniesienia, zgodnej geometrii i materiałów, źródła oraz warunków brzegowych, ustawień numerycznych i porównywanej wielkości.','Dostarczone podsumowanie nie zawiera tych szczegółów na poziomie pozwalającym odtworzyć obliczenia. Nie określa też liczbowo przypadków udanych i nieudanych. Brakujących liczb nie zastępujemy oceną benchmarku ani twierdzeniem o powszechnej zgodności.',rows=[['Proces projektowy','Opisano wewnętrzny przykład. Pozwala omówić pracę inżynierską, lecz nie dowodzi przyjęcia narzędzia przez klientów.'],['Porównanie klasyczne','Wspomniano porównania wewnętrzne; ustawienia odniesienia i liczbowe sukcesy lub rozbieżności są tutaj niedostępne.'],['Przewidywanie neuronowe','Odrębny kierunek badań z ograniczeniami dotyczącymi brzegów, generalizacji i łączenia obszarów.'],['Pomiar fizyczny','Przykład projektowy nie potwierdza wytworzenia ani zmierzonych parametrów pomiaru.']]),
        s('next','Kolejny zestaw dowodów powinien umożliwiać odtworzenie.','Proponowany kolejny etap to możliwy do oceny zapis projektu i symulacji: wersjonowane dane, ustawienia narzędzi, warunki odniesienia, wyniki i znane rozbieżności. Późniejsze porównanie fizyczne wymagałoby własnych dowodów wytworzenia i pomiarów.','To potrzeby dowodowe, a nie zakończone etapy ani obiecane terminy. Demo o uzgodnionym zakresie może wyjaśnić dostępne obecnie elementy procesu i wymagania oceny konkretnego zadania inżynierskiego.',links=['aifield-neural','investors','contact'])],['aifield-design','aifield-neural','artisense-validation','investors','contact'])

